def Bspline(xi, i, p, Xi):
    '''Inputs:
    xi : knot index, integer
    i : polynomial index , integer
    p : polynomial degree of basis function , integer
    Xi : knot vector, 1d array of arbitrary size
    Outputs:
    1d array of size 1, 2 or 3
    '''

    # Base case: degree 0 B-spline (piecewise constant)
    if p == 0:
        # Check if xi is in the interval [Xi[i], Xi[i+1])
        if i < len(Xi) - 1:
            if Xi[i] <= xi < Xi[i + 1]:
                return np.array([1.0])
            else:
                return np.array([0.0])
        else:
            # Handle the right endpoint case
            if xi == Xi[i] and i == len(Xi) - 1:
                return np.array([1.0])
            else:
                return np.array([0.0])

    # Recursive case: degree p > 0
    # Calculate the two coefficients in the Cox-de Boor formula

    # First coefficient: (t - t_i) / (t_{i+p} - t_i)
    denom1 = Xi[i + p] - Xi[i]
    if denom1 == 0:
        alpha = 0.0
    else:
        alpha = (xi - Xi[i]) / denom1

    # Second coefficient: (t_{i+p+1} - t) / (t_{i+p+1} - t_{i+1})
    denom2 = Xi[i + p + 1] - Xi[i + 1]
    if denom2 == 0:
        beta = 0.0
    else:
        beta = (Xi[i + p + 1] - xi) / denom2

    # Recursive calls
    B_i_p_minus_1 = Bspline(xi, i, p - 1, Xi)
    B_i_plus_1_p_minus_1 = Bspline(xi, i + 1, p - 1, Xi)

    # Combine results
    result = alpha * B_i_p_minus_1 + beta * B_i_plus_1_p_minus_1

    return result
